/**
 * Every environment variable the site, its scripts and its tools read: the single source for docs/ENVIRONMENT.md (generated by
 * scripts/env-docs.mjs), for scripts/check-env.mjs, and for the tests that stop this list drifting from the code. A test searches the
 * source for every variable it reads and fails if one is missing here, so add the variable here first.
 *
 * Fields: name; group; purpose; secret (true: never in git, a log, the browser or a report); local / production (what is needed in
 * each place: "required", "optional", "unset" = must NOT be set there); source (where the owner gets it); fallback (the safe default,
 * what happens when it is unset); check (what a well-formed value looks like: see CHECKS in check-env.mjs); held (production: stays
 * unset until the owner approves and flips it).
 */
export const HOSTED_REFS = ["vwsjvdpkgjhwmqmufmrh"]; // the hosted project: its keys must never be in a local environment

